      });

      setRaceData(newData);

      // Check for winner
      if (raceStatus === 'racing') {
        const winner = Object.values(newData).find(racer => racer.percentChange >= TARGET_PERCENT);
        if (winner) {
          setWinner(winner);
          setRaceStatus('finished');
        }
      }
    } catch (error) {
      console.error('Error fetching prices:', error);
    }
  };

  // Start race
  const startRace = async () => {
    setRaceStatus('racing');
    setWinner(null);
    setRaceStartTime(Date.now());
    setElapsedTime(0);

    // Set starting prices
    await fetchPrices();
    const currentPrices = {};
    Object.values(raceData).forEach(racer => {
      if (racer.currentPrice) {
        currentPrices[racer.name] = racer.currentPrice;
      }
    });
    startPricesRef.current = currentPrices;
  };

