import './App.css'

// Pyth MCP integration
async function pythMCP(toolName, args) {
  // Step 1: Initialize session
  const init = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 0, method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'mcp-crypto-racing', version: '1.0' } }
    })
  });
  await init.json();

  // Step 2: Call the tool
  const res = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'tools/call',
      params: { name: toolName, arguments: args }
    })
  });
  const data = await res.json();
  const text = data.result?.content?.[0]?.text || '';
  return JSON.parse(text);
}

const RACERS = [
  { name: 'BTC', symbol: 'Crypto.BTC/USD', color: '#f7931a', icon: '₿' },
  { name: 'ETH', symbol: 'Crypto.ETH/USD', color: '#627eea', icon: 'Ξ' },
  { name: 'SOL', symbol: 'Crypto.SOL/USD', color: '#9945ff', icon: '◎' },
  { name: 'DOGE', symbol: 'Crypto.DOGE/USD', color: '#c2a633', icon: 'Ð' }
];

const TARGET_PERCENT = 3;

function App() {
  const [raceData, setRaceData] = useState({});
  const [raceStatus, setRaceStatus] = useState('waiting'); // waiting, racing, finished
  const [winner, setWinner] = useState(null);
  const [raceStartTime, setRaceStartTime] = useState(null);
  const [elapsedTime, setElapsedTime] = useState(0);
  const startPricesRef = useRef({});

  // Timer effect
  useEffect(() => {
    let interval;
    if (raceStatus === 'racing' && raceStartTime) {
      interval = setInterval(() => {
        setElapsedTime(Math.floor((Date.now() - raceStartTime) / 1000));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [raceStatus, raceStartTime]);

  // Fetch current prices
  const fetchPrices = async () => {
    try {
      const results = await pythMCP('get_historical_price', {
        symbols: RACERS.map(r => r.symbol),
        timestamp: Math.floor(Date.now() / 1000)
      });

      const newData = {};
      RACERS.forEach((racer, index) => {
        const price = results[racer.symbol]?.price;
        if (price) {
          newData[racer.name] = {
            ...racer,
            currentPrice: price,
            startPrice: startPricesRef.current[racer.name] || price,
            percentChange: startPricesRef.current[racer.name] 
              ? ((price - startPricesRef.current[racer.name]) / startPricesRef.current[racer.name]) * 100
              : 0
          };
        }
      });

      setRaceData(newData);

      // Check for winner
      if (raceStatus === 'racing') {
        const winner = Object.values(newData).find(racer => racer.percentChange >= TARGET_PERCENT);
        if (winner) {
          setWinner(winner);
          setRaceStatus('finished');
        }
      }
    } catch (error) {
      console.error('Error fetching prices:', error);
    }
  };

  // Start race
  const startRace = async () => {
    setRaceStatus('racing');
    setWinner(null);
    setRaceStartTime(Date.now());
    setElapsedTime(0);

    // Set starting prices
    await fetchPrices();
    const currentPrices = {};
    Object.values(raceData).forEach(racer => {
      if (racer.currentPrice) {
        currentPrices[racer.name] = racer.currentPrice;
      }
    });
    startPricesRef.current = currentPrices;
  };

  // Reset race
  const resetRace = () => {
    setRaceStatus('waiting');
    setWinner(null);
    setRaceStartTime(null);
    setElapsedTime(0);
    startPricesRef.current = {};
    setRaceData({});
  };

  // Auto-fetch prices during race
  useEffect(() => {
    let interval;
    if (raceStatus === 'racing') {
      fetchPrices(); // Initial fetch
      interval = setInterval(fetchPrices, 2000); // Update every 2 seconds
    }
    return () => clearInterval(interval);
  }, [raceStatus]);

  // Format time
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="app">
      <header className="header">
        <h1>🏁 Crypto Price Racing</h1>
        <p>First to +{TARGET_PERCENT}% wins!</p>
      </header>

      <div className="race-info">
        <div className="status">
          Status: <span className={`status-${raceStatus}`}>
            {raceStatus === 'waiting' && 'Ready to Race'}
            {raceStatus === 'racing' && `Racing... ${formatTime(elapsedTime)}`}
            {raceStatus === 'finished' && `🏆 ${winner?.name} WINS!`}
          </span>
        </div>

        {raceStatus !== 'racing' && (
          <button 
            className="race-btn start-btn"
            onClick={startRace}
          >
            {raceStatus === 'waiting' ? '🚀 Start Race' : '🔄 New Race'}
          </button>
        )}

        {raceStatus === 'racing' && (
          <button 
            className="race-btn reset-btn"
            onClick={resetRace}
          >
            ⏹️ Reset
          </button>
        )}
      </div>

      <div className="racetrack">
        {RACERS.map(racer => {
          const racerData = raceData[racer.name];
          const progress = racerData 
            ? Math.min((racerData.percentChange / TARGET_PERCENT) * 100, 100)
            : 0;

          return (
            <div key={racer.name} className="racer-lane">
              <div className="racer-info">
                <div className="racer-icon" style={{ color: racer.color }}>
                  {racer.icon}
                </div>
                <div className="racer-details">
                  <div className="racer-name">{racer.name}</div>
                  <div className="racer-price">
                    {racerData ? `$${racerData.currentPrice?.toFixed(2)}` : '...'}
                  </div>
                  <div className="racer-percent" style={{ 
                    color: racerData?.percentChange >= 0 ? '#00ff88' : '#ff4444' 
                  }}>
                    {racerData ? `${racerData.percentChange >= 0 ? '+' : ''}${racerData.percentChange.toFixed(2)}%` : '0.00%'}
                  </div>
                </div>
              </div>

              <div className="race-lane">
                <div className="track"></div>
                <div 
                  className="racer-position"
                  style={{ 
                    left: `${progress}%`,
                    backgroundColor: racer.color,
                    boxShadow: winner?.name === racer.name ? `0 0 20px ${racer.color}` : 'none'
                  }}
                >
                  {racer.icon}
                </div>
                <div className="finish-line">🏁</div>
              </div>
            </div>
          );
        })}
      </div>

      {winner && (
        <div className="winner-celebration">
          <div className="winner-text">
            🎉 {winner.name} wins with +{winner.percentChange.toFixed(2)}% in {formatTime(elapsedTime)}!
          </div>
        </div>
      )}
    </div>
  );
}

export default App;"}

