{"path": "src/App.jsx", "content": "import React, { useState, useEffect, useRef } from 'react'
import './App.css'

// Pyth MCP integration
async function pythMCP(toolName, args) {
  // Step 1: Initialize session
  const init = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 0, method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'mcp-crypto-racing', version: '1.0' } }
    })
  });
  await init.json();

  // Step 2: Call the tool
  const res = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'tools/call',
      params: { name: toolName, arguments: args }
    })
  });
  const data = await res.json();
  const text = data.result?.content?.[0]?.text || '';
  return JSON.parse(text);
}

const RACERS = [
  { name: 'BTC', symbol: 'Crypto.BTC/USD', color: '#f7931a', icon: '₿' },
  { name: 'ETH', symbol: 'Crypto.ETH/USD', color: '#627eea', icon: 'Ξ' },
  { name: 'SOL', symbol: 'Crypto.SOL/USD', color: '#9945ff', icon: '◎' },
  { name: 'DOGE', symbol: 'Crypto.DOGE/USD', color: '#c2a633', icon: 'Ð' }
];

const TARGET_PERCENT = 3;

function App() {
  const [raceData, setRaceData] = useState({});
  const [raceStatus, setRaceStatus] = useState('waiting'); // waiting, racing, finished
  const [winner, setWinner] = useState(null);
  const [raceStartTime, setRaceStartTime] = useState(null);
  const [elapsedTime, setElapsedTime] = useState(0);
  const startPricesRef = useRef({});

  // Timer effect
  useEffect(() => {
    let interval;
    if (raceStatus === 'racing' && raceStartTime) {
      interval = setInterval(() => {
        setElapsedTime(Math.floor((Date.now() - raceStartTime) / 1000));
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [raceStatus, raceStartTime]);

  // Fetch current prices
  const fetchPrices = async () => {
    try {
      const results = await pythMCP('get_historical_price', {
        symbols: RACERS.map(r => r.symbol),
        timestamp: Math.floor(Date.now() / 1000)
      });

      const newData = {};
      RACERS.forEach((racer, index) => {
        const price = results[racer.symbol]?.price;
        if (price) {
          newData[racer.name] = {
            ...racer,
            currentPrice: price,
            startPrice: startPricesRef.current[racer.name] || price,
            percentChange: startPricesRef.current[racer.name] 
              ? ((price - startPricesRef.current[racer.name]) / startPricesRef.current[racer.name]) * 100
              : 0
          };
        }
      });

      setRaceData(newData);

      // Check for winner
      if (raceStatus === 'racing') {
        const winner = Object.values(newData).find(racer => racer.percentChange >= TARGET_PERCENT);
        if (winner) {
          setWinner(winner);
          setRaceStatus('finished');
        }
      }
    } catch (error) {
      console.error('Error fetching prices:', error);
    }
  };

  // Start race
  const startRace = async () => {
    setRaceStatus('racing');
    setWinner(null);
    setRaceStartTime(Date.now());
    setElapsedTime(0);

    // Set starting prices
    await fetchPrices();
    const currentPrices = {};
    Object.values(raceData).forEach(racer => {
      if (racer.currentPrice) {
        currentPrices[racer.name] = racer.currentPrice;
      }
    });
    startPricesRef.current = currentPrices;
  };

  // Reset race
  const resetRace = () => {
    setRaceStatus('waiting');
    setWinner(null);
    setRaceStartTime(null);
    setElapsedTime(0);
    startPricesRef.current = {};
    setRaceData({});
  };

  // Auto-fetch prices during race
  useEffect(() => {
    let interval;
    if (raceStatus === 'racing') {
      fetchPrices(); // Initial fetch
      interval = setInterval(fetchPrices, 2000); // Update every 2 seconds
    }
    return () => clearInterval(interval);
  }, [raceStatus]);

  // Format time
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="app">
      <header className="header">
        <h1>🏁 Crypto Price Racing</h1>
        <p>First to +{TARGET_PERCENT}% wins!</p>
      </header>

      <div className="race-info">
        <div className="status">
          Status: <span className={`status-${raceStatus}`}>
            {raceStatus === 'waiting' && 'Ready to Race'}
            {raceStatus === 'racing' && `Racing... ${formatTime(elapsedTime)}`}
            {raceStatus === 'finished' && `🏆 ${winner?.name} WINS!`}
          </span>
        </div>

        {raceStatus !== 'racing' && (
          <button 
            className="race-btn start-btn"
            onClick={startRace}
          >
            {raceStatus === 'waiting' ? '🚀 Start Race' : '🔄 New Race'}
          </button>
        )}

        {raceStatus === 'racing' && (
          <button 
            className="race-btn reset-btn"
            onClick={resetRace}
          >
            ⏹️ Reset
          </button>
        )}
      </div>

      <div className="racetrack">
        {RACERS.map(racer => {
          const racerData = raceData[racer.name];
          const progress = racerData 
            ? Math.min((racerData.percentChange / TARGET_PERCENT) * 100, 100)
            : 0;

          return (
            <div key={racer.name} className="racer-lane">
              <div className="racer-info">
                <div className="racer-icon" style={{ color: racer.color }}>
                  {racer.icon}
                </div>
                <div className="racer-details">
                  <div className="racer-name">{racer.name}</div>
                  <div className="racer-price">
                    {racerData ? `$${racerData.currentPrice?.toFixed(2)}` : '...'}
                  </div>
                  <div className="racer-percent" style={{ 
                    color: racerData?.percentChange >= 0 ? '#00ff88' : '#ff4444' 
                  }}>
                    {racerData ? `${racerData.percentChange >= 0 ? '+' : ''}${racerData.percentChange.toFixed(2)}%` : '0.00%'}
                  </div>
                </div>
              </div>

              <div className="race-lane">
                <div className="track"></div>
                <div 
                  className="racer-position"
                  style={{ 
                    left: `${progress}%`,
                    backgroundColor: racer.color,
                    boxShadow: winner?.name === racer.name ? `0 0 20px ${racer.color}` : 'none'
                  }}
                >
                  {racer.icon}
                </div>
                <div className="finish-line">🏁</div>
              </div>
            </div>
          );
        })}
      </div>

      {winner && (
        <div className="winner-celebration">
          <div className="winner-text">
            🎉 {winner.name} wins with +{winner.percentChange.toFixed(2)}% in {formatTime(elapsedTime)}!
          </div>
        </div>
      )}
    </div>
  );
}

export default App;"}

{"path": "src/App.css", "content": ".app {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
  min-height: 100vh;
}

.header {
  text-align: center;
  margin-bottom: 30px;
}

.header h1 {
  font-size: 2.5rem;
  margin-bottom: 10px;
  background: linear-gradient(45deg, #ff6b6b, #4ecdc4, #45b7d1, #96ceb4);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: gradient 3s ease infinite;
}

.header p {
  font-size: 1.2rem;
  color: #888;
}

@keyframes gradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.race-info {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 40px;
  padding: 20px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 15px;
  backdrop-filter: blur(10px);
}

.status {
  font-size: 1.2rem;
  font-weight: 600;
}

.status-waiting { color: #ffd700; }
.status-racing { color: #00ff88; }
.status-finished { color: #ff6b6b; }

.race-btn {
  padding: 12px 24px;
  border: none;
  border-radius: 25px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.start-btn {
  background: linear-gradient(45deg, #00ff88, #00cc6a);
  color: white;
}

.start-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(0, 255, 136, 0.3);
}

.reset-btn {
  background: linear-gradient(45deg, #ff4444, #cc3333);
  color: white;
}

.reset-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 5px 15px rgba(255, 68, 68, 0.3);
}

.racetrack {
  background: rgba(255, 255, 255, 0.02);
  border-radius: 20px;
  padding: 30px;
  margin-bottom: 30px;
}

.racer-lane {
  display: flex;
  align-items: center;
  margin-bottom: 30px;
  gap: 20px;
}

.racer-info {
  display: flex;
  align-items: center;
  gap: 15px;
  min-width: 200px;
  flex-shrink: 0;
}

.racer-icon {
  font-size: 2rem;
  font-weight: bold;
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  border: 2px solid currentColor;
}

.racer-details {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.racer-name {
  font-size: 1.2rem;
  font-weight: bold;
  color: #fff;
}

.racer-price {
  font-size: 0.9rem;
  color: #ccc;
}

.racer-percent {
  font-size: 1rem;
  font-weight: 600;
}

.race-lane {
  position: relative;
  flex: 1;
  height: 60px;
  display: flex;
  align-items: center;
}

.track {
  width: 100%;
  height: 8px;
  background: linear-gradient(90deg, #333 0%, #444 50%, #333 100%);
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.track::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 2px;
  background: repeating-linear-gradient(90deg, 
    transparent 0px, 
    transparent 20px, 
    #666 20px, 
    #666 40px
  );
  transform: translateY(-50%);
}

.racer-position {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: bold;
  color: white;
  transition: left 0.5s ease;
  z-index: 2;
  border: 2px solid rgba(255, 255, 255, 0.3);
}

.finish-line {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  font-size: 2rem;
  z-index: 1;
}

.winner-celebration {
  text-align: center;
  padding: 30px;
  background: linear-gradient(45deg, #ff6b6b, #ffd700);
  border-radius: 20px;
  animation: celebrate 2s ease-in-out;
}

.winner-text {
  font-size: 1.5rem;
  font-weight: bold;
  color: white;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
}

@keyframes celebrate {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}

@media (max-width: 768px) {
  .app {
    padding: 15px;
  }

  .header h1 {
    font-size: 2rem;
  }

  .race-info {
    flex-direction: column;
    gap: 15px;
  }

  .racer-lane {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }

  .racer-info {
    justify-content: center;
    min-width: auto;
  }

  .race-lane {
    margin-top: 10px;
  }
}"}
